/* Connect the recommendation rules to existing workspace actions and forms. */
const R=window.UniifyRecommendations;
let managerUpdating=false;
const managerSave=save;
save=function(message){if(!managerUpdating){managerUpdating=true;const changes=R.reconcile(state,new Date().toISOString());if(changes.length)adapt('Career recommendations updated from your assessment, goal and available resources');managerUpdating=false;}managerSave(message)};
proposed=function(){return R.suggest(state)};
applyPlan=function(){const changes=R.reconcile(state,new Date().toISOString());adapt('Career recommendations reviewed');save(changes.length?'Recommendations updated.':'Your recommendations are current.');closeDialog();location.hash='roadmap';render()};
const managerAssessment=assessment;
assessment=function(){let html=managerAssessment();const p=state.profile;return html.replace('<div class="panel-head"><h2>Your foundations check</h2>',`<div class="fields manager-context">${select('Career stage','context_stage',['Just starting','Released music, building an audience','Growing my career','Established independent artist'],p.stage)}${select('Primary goal','context_goal',['Release my first music','Grow my audience','Earn more from music','Improve career management','Find collaborators and opportunities'],p.goal)}${select('Current challenge','context_challenge',['Knowing what to do next','Budget and resources','Marketing and audience growth','Managing releases and tasks','Industry connections'],p.challenge)}${select('Hours each week','context_hours',['1–3 hours','4–7 hours','8–15 hours','16+ hours'],p.hours)}${field('Released tracks','context_tracks',p.tracks,'number','min="0" max="100000" step="1"')}${field('Monthly music budget','context_budget',p.budget,'number','min="0" max="100000000" step="0.01"')}${select('Currency','context_currency',['GBP','NGN','USD','EUR'],p.currency||'GBP')}<label class="field full"><span>Strengths</span><textarea name="context_strengths" maxlength="1500">${esc(p.strengths||'')}</textarea></label><label class="field full"><span>Current obstacles</span><textarea name="context_obstacles" maxlength="1500">${esc(p.obstacles||'')}</textarea></label></div><p class="small-copy muted">Blank answers remain unknown. <a href="#career">Record platform-specific audience observations in Career Progress.</a></p><div class="panel-head"><h2>Your foundations check</h2>`)};
document.addEventListener('submit',e=>{const f=e.target;if(f.id==='assessment-form'){const data=Object.fromEntries(new FormData(f));if((state.entries.length||state.releases.some(r=>Number(r.budget)>0))&&data.context_currency!==(state.profile.currency||'GBP')){e.preventDefault();e.stopImmediatePropagation();toast('Keep the current currency while financial records exist.');return;}for(const [k,v]of Object.entries(data))if(k.startsWith('context_'))state.profile[k.slice(8)]=v;}
 if(f.id==='manager-checkin'){e.preventDefault();e.stopImmediatePropagation();const data=Object.fromEntries(new FormData(f));state.checkins||=[];state.checkins.push({id:uid(),date:today(),time:new Date().toISOString(),completed:data.completed,obstacle:data.obstacle});state.profile.obstacles=data.obstacle;if(data.hours)state.profile.hours=data.hours;record('checkin_completed','checkin','Weekly career review completed');save('Check-in saved. Recommendations reviewed.');closeDialog();render();}
},true);
const managerOverview=overview;
overview=function(){const next=activeTasks().filter(t=>!['Done','Deferred'].includes(t.status)&&!E.blocked(state,t)).sort((a,b)=>(b.priority||0)-(a.priority||0)||(a.order||0)-(b.order||0)).slice(0,3);const last=state.checkins?.at(-1);const due=!last||E.shift(last.date,7)<=today();return managerOverview()+`<section class="panel manager-next"><div class="panel-head"><h2>Recommended next actions</h2>${link('Career assessment','assessment')}</div>${next.length?next.map(t=>`<article class="manager-action"><h3><button class="text-link" data-task="${t.id}">${esc(t.title)}</button></h3><p>${esc(t.reason||'An action in your career plan.')}</p><small>${t.effort||t.minutes||30} minutes · ${esc(t.releaseId?state.releases.find(r=>r.id===t.releaseId)?.title||'Release':'General career work')}</small></article>`).join(''):'<p>Complete your assessment or create a release to choose your next steps.</p>'}</section><section class="panel manager-next"><div class="panel-head"><h2>Weekly check-in</h2><button class="text-link" data-manager-checkin>Review your week</button></div><p>${due?'Your review is due. Record what moved forward and what got in the way.':'Last reviewed '+date(last.date)+'. Next review '+date(E.shift(last.date,7))+'.'}</p></section>`};
const managerNotice=scheduleNotice;scheduleNotice=function(){const history=state.recommendationHistory?.at(-1);return managerNotice()+(history?`<details class="panel"><summary>Recommendation changes · ${date(history.time.slice(0,10))}</summary><ul>${history.changes.map(c=>`<li>${esc(c)}</li>`).join('')}</ul><p class="small-copy muted">Based on your saved inputs using planning rules. Undo above restores automatic scheduling changes only.</p></details>`:'')};
const managerSettings=settings;settings=function(){if(!window.uniifyCloud)return managerSettings();return header('Settings & data')+`<section class="panel"><h2>Private cloud workspace</h2><p>Your records sync to your account. Pending changes are retained on this device when a save fails. The save status is shown in the header.</p><div class="form-actions">${btn('Export workspace','export','download')}<button class="text-link" data-cloud-retry>Retry save</button></div></section>`};
const managerProfile=profile;profile=function(){return managerProfile().replace('Saved only in this browser.',window.uniifyCloud?'Saved to your private cloud workspace.':'Saved on this device.')};
document.addEventListener('click',e=>{if(e.target.closest('[data-manager-checkin]'))openDialog('Weekly check-in',`<form id="manager-checkin"><div class="fields"><label class="field full"><span>What moved forward?</span><textarea name="completed" maxlength="2000" required></textarea></label><label class="field full"><span>What got in the way?</span><textarea name="obstacle" maxlength="2000"></textarea></label>${select('Hours next week','hours',['1–3 hours','4–7 hours','8–15 hours','16+ hours'],state.profile.hours)}</div><button class="theme-btn-two">Save check-in</button></form>`);if(e.target.closest('[data-cloud-retry]'))window.uniifyCloud?.flush();});
if(!state.history.length&&!state.releases.length&&!location.hash)location.hash='assessment';
save();render();

/* Artist-owned links share the profile's existing cloud/local persistence. */
(()=>{
const platforms=['Instagram','Facebook','TikTok','YouTube','X','Threads','Spotify','Apple Music','SoundCloud','Bandcamp','Audiomack','Deezer','Website'];
const safeURL=value=>{try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)&&!u.username&&!u.password?u.href:''}catch{return ''}};
const row=(name='',url='',custom=false)=>`<div class="artist-link-row" data-link-row>${custom?`<label class="field"><span>Link name</span><input name="link-label" value="${esc(name)}" maxlength="60" placeholder="e.g. Press kit" required></label>`:`<input name="link-label" type="hidden" value="${esc(name)}">`}<label class="field"><span>${custom?'URL':esc(name)}</span><input name="link-url" type="url" value="${esc(url)}" placeholder="https://" maxlength="2048" ${custom?'required':''}></label><button class="text-link" type="button" data-remove-link aria-label="Remove link">Remove</button></div>`;
function section(){const links=Array.isArray(state.profile.links)?state.profile.links:[];return `<section class="panel artist-links"><h2>Social & streaming links</h2><p class="small-copy muted">Keep your artist pages, music and other useful links together. These links stay in your private workspace.</p><form id="artist-links-form"><div class="fields">${links.filter(l=>platforms.includes(l.label)).map(l=>row(l.label,l.url)).join('')}</div><label class="field link-picker"><span>Add a platform</span><select data-platform-picker><option value="">Choose a social or streaming platform</option>${platforms.filter(name=>!links.some(l=>l.label===name)).map(name=>`<option>${esc(name)}</option>`).join('')}</select></label><h3>Other links</h3><div id="custom-artist-links">${links.filter(l=>!platforms.includes(l.label)).map(l=>row(l.label,l.url,true)).join('')}</div><button type="button" class="text-link" data-add-link>Add another link</button><div class="form-actions"><button type="submit" class="theme-btn-two">Save links</button></div><p role="status" data-links-status></p></form></section>`}
const originalProfile=profile,originalSettings=settings;
profile=function(){return originalProfile()+section()};settings=function(){return originalSettings()+section()};
document.addEventListener('change',e=>{if(e.target.matches('[data-platform-picker]')&&e.target.value){const name=e.target.value;e.target.closest('form').querySelector('.fields').insertAdjacentHTML('beforeend',row(name));e.target.selectedOptions[0].remove();e.target.value='';}});
document.addEventListener('click',e=>{if(e.target.closest('[data-add-link]')){const holder=document.querySelector('#custom-artist-links');if(holder.children.length>=20){toast('You can add up to 20 other links.');return}holder.insertAdjacentHTML('beforeend',row('','',true));holder.lastElementChild.querySelector('input').focus()}if(e.target.closest('[data-remove-link]'))e.target.closest('[data-link-row]').remove()});
document.addEventListener('submit',e=>{if(e.target.id!=='artist-links-form')return;e.preventDefault();const links=[];for(const r of e.target.querySelectorAll('[data-link-row]')){const label=r.querySelector('[name=link-label]').value.trim(),raw=r.querySelector('[name=link-url]').value.trim();if(!raw)continue;const url=safeURL(raw);if(!url||!label||label.length>60||raw.length>2048){e.target.querySelector('[data-links-status]').textContent='Use a name and a valid http:// or https:// link for each entry.';return}links.push({label,url})}state.profile.links=links;save('Artist links saved.');render()},true);
render();
})();

/* Compact workspace controls and editable artist imagery. */
(()=>{
const pencil='<i class="fa-light fa-pen" aria-hidden="true"></i>';
const oldProfile=profile;profile=function(){const t=document.createElement('template');t.innerHTML=oldProfile();const photo=t.content.querySelector('.profile-photo');photo.innerHTML=`<div class="photo-editor"><button type="button" class="profile-avatar" data-photo-menu aria-label="Edit profile photo">${state.profile.photo?`<img src="${esc(state.profile.photo)}" alt="Artist profile photo">`:esc((state.profile.artist||'U')[0])}</button><button type="button" class="photo-edit" data-photo-menu aria-label="Edit profile photo">${pencil}</button><div class="photo-options" hidden><label>Choose photo<input id="profile-photo" type="file" accept="image/jpeg,image/png,image/webp" hidden></label>${state.profile.photo?'<button type="button" id="remove-photo">Remove photo</button>':''}</div></div><div><h2>${esc(state.profile.artist||'Your artist profile')}</h2><p class="muted small-copy">Your identity, career and connections.</p></div>`;t.content.querySelector('#profile-form').classList.add('profile-essentials');return t.innerHTML};
const oldOverview=overview;overview=function(){return oldOverview().replace('<section class="workspace-banner">',`<section class="workspace-banner">${state.profile.cover?`<img class="custom-cover" src="${esc(state.profile.cover)}" alt="">`:''}<button class="cover-edit" data-edit-cover aria-label="Edit cover photo" title="Edit cover photo">${pencil}</button>`)};
const oldRoadmap=roadmap;roadmap=function(){const t=document.createElement('template');t.innerHTML=oldRoadmap();const toolbar=t.content.querySelector('.toolbar'),switcher=t.content.querySelector('.view-switch');toolbar.classList.add('roadmap-toolbar');toolbar.append(switcher);return t.innerHTML};
const menuButton=document.querySelector('#menu-toggle');menuButton.innerHTML='<i class="fa-light fa-sidebar" aria-hidden="true"></i>';menuButton.title='Collapse or expand sidebar';menuButton.setAttribute('aria-label','Collapse or expand sidebar');document.querySelector('.uniify-brand').after(menuButton);
document.addEventListener('click',e=>{if(e.target.closest('[data-photo-menu]')){const options=document.querySelector('.photo-options');options.hidden=!options.hidden;}else if(!e.target.closest('.photo-editor')){const options=document.querySelector('.photo-options');if(options)options.hidden=true;}
if(e.target.closest('[data-edit-cover]'))openDialog('Cover photo',`<div class="cover-options"><label class="theme-btn-two">Choose cover photo<input id="cover-photo" type="file" accept="image/jpeg,image/png,image/webp" hidden></label>${state.profile.cover?'<button type="button" class="text-link" data-remove-cover>Remove cover</button>':''}<p class="small-copy muted">Choose a landscape image, up to 10 MB.</p></div>`);
if(e.target.closest('[data-remove-cover]')){delete state.profile.cover;save('Cover removed.');closeDialog();render();}
if(e.target.closest('[data-logout]')){e.preventDefault();const signout=document.querySelector('#account-links [data-signout]');if(signout)signout.click();else location.href='/signin';}});
document.addEventListener('change',async e=>{if(e.target.id!=='cover-photo')return;const file=e.target.files[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024){toast('Choose a JPG, PNG or WebP under 10 MB.');return}try{const bitmap=await createImageBitmap(file),canvas=document.createElement('canvas');canvas.width=1200;canvas.height=450;const scale=Math.max(1200/bitmap.width,450/bitmap.height),width=bitmap.width*scale,height=bitmap.height*scale;canvas.getContext('2d').drawImage(bitmap,(1200-width)/2,(450-height)/2,width,height);state.profile.cover=canvas.toDataURL('image/jpeg',.8);bitmap.close();save('Cover updated.');closeDialog();render()}catch{toast('This image could not be opened.')}});
render();
})();
